CREATE TABLE live_sources(id TEXT PRIMARY KEY,name TEXT NOT NULL,protected_input TEXT NOT NULL,enabled INTEGER NOT NULL,revision INTEGER NOT NULL DEFAULT 1,tuners INTEGER NOT NULL DEFAULT 2,created_by TEXT NOT NULL REFERENCES users(id),next_sync TEXT NOT NULL,last_sync TEXT,last_error TEXT);
CREATE TABLE live_channels(id TEXT PRIMARY KEY,source_id TEXT NOT NULL REFERENCES live_sources(id),source_key TEXT NOT NULL,name TEXT NOT NULL,group_name TEXT NOT NULL,epg_id TEXT,epg_override TEXT,logo TEXT,protected_url TEXT NOT NULL,radio INTEGER NOT NULL DEFAULT 0,enabled INTEGER NOT NULL DEFAULT 1,available INTEGER NOT NULL DEFAULT 1,minimum_age INTEGER,ordinal INTEGER NOT NULL DEFAULT 0,UNIQUE(source_id,source_key));
CREATE TABLE live_programmes(id TEXT PRIMARY KEY,channel_id TEXT NOT NULL REFERENCES live_channels(id),starts_at TEXT NOT NULL,ends_at TEXT NOT NULL,title TEXT NOT NULL,title_key TEXT NOT NULL,description TEXT NOT NULL,episode_key TEXT NOT NULL,repeat INTEGER,minimum_age INTEGER,UNIQUE(channel_id,starts_at));
CREATE INDEX live_epg_times ON live_programmes(channel_id,starts_at,ends_at);
CREATE TABLE live_sessions(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),login_id TEXT NOT NULL,device_id TEXT NOT NULL,channel_id TEXT NOT NULL REFERENCES live_channels(id),source_revision INTEGER NOT NULL,status TEXT NOT NULL,created_at TEXT NOT NULL,last_seen TEXT NOT NULL,error TEXT);
CREATE INDEX live_sessions_active ON live_sessions(status,channel_id);
CREATE TABLE dvr_rules(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),user_version INTEGER NOT NULL,channel_id TEXT NOT NULL REFERENCES live_channels(id),title TEXT NOT NULL,title_key TEXT NOT NULL,enabled INTEGER NOT NULL,only_new INTEGER NOT NULL,padding_before INTEGER NOT NULL,padding_after INTEGER NOT NULL,priority INTEGER NOT NULL,revision INTEGER NOT NULL DEFAULT 1);
CREATE TABLE dvr_recordings(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),user_version INTEGER NOT NULL,channel_id TEXT NOT NULL REFERENCES live_channels(id),programme_id TEXT REFERENCES live_programmes(id),rule_id TEXT REFERENCES dvr_rules(id),episode_key TEXT NOT NULL,title TEXT NOT NULL,starts_at TEXT NOT NULL,ends_at TEXT NOT NULL,minimum_age INTEGER,priority INTEGER NOT NULL,status TEXT NOT NULL,revision INTEGER NOT NULL DEFAULT 1,lease TEXT,message TEXT NOT NULL DEFAULT '',bytes INTEGER NOT NULL DEFAULT 0,media_id TEXT REFERENCES media(id),created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE UNIQUE INDEX dvr_episode_once ON dvr_recordings(user_id,episode_key) WHERE status NOT IN ('failed','cancelled');
CREATE TABLE dvr_exclusions(user_id TEXT NOT NULL REFERENCES users(id),episode_key TEXT NOT NULL,PRIMARY KEY(user_id,episode_key));
CREATE TRIGGER dvr_rule_changed AFTER UPDATE OF enabled,only_new,padding_before,padding_after,priority ON dvr_rules BEGIN
 UPDATE dvr_recordings SET status='cancelled',revision=revision+1,lease=NULL,message='Kayıt kuralı değişti; gelecek yayınlar yeni tercihle planlanacak.'
 WHERE rule_id=NEW.id AND status IN ('scheduled','conflict');
END;
